/* =========================================================
   CONTROLADOR DE NAVEGACIÓN DE CONDICIÓN 5 (INVESTIGACIÓN PPT)
   ========================================================= */
(function() {
    let currentSlide = 1;
    const totalSlides = 30;

    const ejeMapping = {
        1: [1, 2, 3, 4, 5, 6],
        2: [7, 8, 9, 10, 11, 12, 13],
        3: [14, 15],
        4: [16, 17, 18, 19, 20],
        5: [21, 22, 23],
        6: [24, 25, 26],
        7: [27, 28, 29, 30]
    };

    window.goToC5Slide = function(slideNum) {
        if (slideNum < 1 || slideNum > totalSlides) return;
        currentSlide = slideNum;

        // 1. Update pills
        document.querySelectorAll('.c5-slide-pill').forEach(btn => {
            const num = parseInt(btn.getAttribute('data-c5-slide-btn'), 10);
            if (num === currentSlide) {
                btn.classList.add('active');
                btn.style.background = '#F39200';
                btn.style.color = '#FFFFFF';
                btn.style.borderColor = '#F39200';
            } else {
                btn.classList.remove('active');
                btn.style.background = '#FFFFFF';
                btn.style.color = '#334155';
                btn.style.borderColor = '#CBD5E1';
            }
        });

        // 2. Update active eje button
        let activeEjeId = 1;
        for (const [ejeId, slideList] of Object.entries(ejeMapping)) {
            if (slideList.includes(currentSlide)) {
                activeEjeId = parseInt(ejeId, 10);
                break;
            }
        }
        document.querySelectorAll('.c5-eje-btn').forEach(btn => {
            const eid = parseInt(btn.getAttribute('data-c5-eje'), 10);
            if (eid === activeEjeId) {
                btn.classList.add('active');
                btn.style.background = '#1A1A1B';
                btn.style.color = '#FFFFFF';
                btn.style.border = '1.5px solid #F39200';
            } else {
                btn.classList.remove('active');
                btn.style.background = '#FFFFFF';
                btn.style.color = '#4A4A4A';
                btn.style.border = '1px solid #E2E8F0';
            }
        });

        // 3. Show slide panel, hide others
        document.querySelectorAll('.c5-slide-panel').forEach(panel => {
            panel.classList.remove('active');
            panel.style.display = 'none';
        });

        const targetPanel = document.getElementById('c5-slide-panel-' + currentSlide);
        if (targetPanel) {
            targetPanel.classList.add('active');
            targetPanel.style.display = 'block';
        }

        // 4. Scroll smoothly to top
        const scroller = document.getElementById('scrollContainer') || document.querySelector('.presentation-viewer-content') || window;
        if (scroller.scrollTo) {
            scroller.scrollTo({ top: 0, behavior: 'smooth' });
        } else if (scroller.scrollTop !== undefined) {
            scroller.scrollTop = 0;
        }
    };

    window.nextC5Slide = function() {
        if (currentSlide < totalSlides) {
            window.goToC5Slide(currentSlide + 1);
        }
    };

    window.prevC5Slide = function() {
        if (currentSlide > 1) {
            window.goToC5Slide(currentSlide - 1);
        }
    };

    window.switchC5Eje = function(ejeId) {
        const slideList = ejeMapping[ejeId];
        if (slideList && slideList.length > 0) {
            window.goToC5Slide(slideList[0]);
        }
    };

    window.c5Init = function() {
        window.goToC5Slide(1);
    };
})();

